q210.from:
round(coalesce(u.unpaid_eur, 0), 2) as unpaid_invoice_balance_eur,
round(case when tr.q3_sessions is null or tr.q3_sessions = 0 then null
           else 100.0 * (tr.q4_sessions - tr.q3_sessions) / tr.q3_sessions end, 1) as traffic_change_pct_q4_vs_q3,
round(case when r.q3_fee is null or r.q3_fee = 0 then null
           else 100.0 * (r.q4_fee - r.q3_fee) / r.q3_fee end, 1) as fee_revenue_change_pct_q4_vs_q3,

q210.to:
coalesce(u.unpaid_eur, 0) as unpaid_invoice_balance_eur,
case when tr.q3_sessions is null or tr.q3_sessions = 0 then null
     else 100.0 * (tr.q4_sessions - tr.q3_sessions) / tr.q3_sessions end as traffic_change_pct_q4_vs_q3,
case when r.q3_fee is null or r.q3_fee = 0 then null
     else 100.0 * (r.q4_fee - r.q3_fee) / r.q3_fee end as fee_revenue_change_pct_q4_vs_q3,

q312.from:
ROUND(
  100.0 * COUNT(*) FILTER (
    WHERE EXISTS (
      SELECT 1 FROM audit_log al
      WHERE al.entity_table = 'orders'
        AND al.entity_id = o.id
        AND al.tenant_id = o.tenant_id
    )
  ) / NULLIF(COUNT(*), 0), 1
) AS coverage_rate_pct,

ROUND(
  100.0 * COUNT(*) FILTER (
    WHERE EXISTS (
      SELECT 1 FROM audit_log al
      WHERE al.entity_table = 'invoices'
        AND al.entity_id = i.id
        AND al.tenant_id = i.tenant_id
    )
  ) / NULLIF(COUNT(*), 0), 1
) AS coverage_rate_pct,

q323.from:
round(
  percentile_cont(0.5) WITHIN GROUP (
    ORDER BY extract(epoch FROM (completed_at - received_at)) / 86400.0
  ) FILTER (WHERE completed_at IS NOT NULL),
  1
) AS median_days_to_close

q323.to:
  percentile_cont(0.5) WITHIN GROUP (
ORDER BY extract(epoch FROM (completed_at - received_at)) / 86400.0
) FILTER (WHERE completed_at IS NOT NULL) AS median_days_to_close

q409.from:
round(avg(extract(epoch from (ft.resolved_at - ft.created_at)) / 60.0)) AS avg_resolution_minutes_after_exclusion,
round(
  100.0 * sum(
    case when exists (
      select 1 from sla_breaches sb
      where sb.ticket_id = ft.ticket_id and sb.breach_kind = 'resolution'
    ) then 1 else 0 end
  ) / count(*),
  1
) AS resolution_breach_rate_after_exclusion
